// The caller's bytes stay where they are; native code reads them in place.
const bytes = new Uint8Array(16 * 1024 * 1024);
const hash = native.checksum(bytes);   // one call, no copy

// WebAssembly cannot read a JS array in place: copy it into linear memory first.
const ptr = wasm.alloc(data.byteLength);
new Int32Array(wasm.memory.buffer, ptr, data.length).set(data);   // on every call
const sum = wasm.sum_i32(ptr, data.length);

// Native code builds one JS object per row, 10,000 times.
const rows = native.query(sql);         // [{ id, score, active, name }, …]

// Packed: one buffer comes back and is decoded into objects in JS.
const packed = native.queryPacked(sql);
